/**
 * Seo Engine smoke test: one user signs in, then opens every project page once.
 *
 * Run against a LOCAL dev server with the test database (never the live site: pages make real Google calls).
 *   k6 run k6/scripts/seo-engine-smoke.js
 * Override with: -e BASE_URL=... -e PROJECT_ID=... -e EMAIL=... -e PASSWORD=...
 */
import http from 'k6/http';
import { check, fail } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://localhost:3000';
const PROJECT_ID = __ENV.PROJECT_ID || 'cmwiyvoy10000a07db4l2kysf';
const EMAIL = __ENV.EMAIL || 'admin@agency.test';
const PASSWORD = __ENV.PASSWORD || 'admin-demo-pass-1';

const PAGES = [
  '',
  'performance',
  'rankings',
  'referrals',
  'backlinks',
  'audit',
  'reports',
  'settings',
  'shopping',
  'shopping/notifications',
  'shopping/products',
  'shopping/shipping',
  'shopping/feeds',
  'shopping/settings',
];

export const options = {
  vus: 1,
  iterations: 1,
  thresholds: {
    checks: ['rate==1'],
    http_req_failed: ['rate==0'],
    // The dev server compiles pages on first visit, so allow a generous ceiling
    http_req_duration: ['p(95)<20000'],
  },
};

export default function () {
  // Sign in with the credentials provider: fetch a CSRF token, post the form, keep the session cookie
  const csrf = http.get(`${BASE_URL}/api/auth/csrf`);
  const csrfOk = check(csrf, { 'csrf token issued': (r) => r.status === 200 && !!r.json('csrfToken') });
  if (!csrfOk) fail('could not get a CSRF token; is the dev server running?');

  http.post(`${BASE_URL}/api/auth/callback/credentials`, {
    csrfToken: csrf.json('csrfToken'),
    email: EMAIL,
    password: PASSWORD,
    callbackUrl: `${BASE_URL}/projects`,
  });

  const projects = http.get(`${BASE_URL}/projects`);
  const signedIn = check(projects, {
    'signed in (projects page, not sign-in)': (r) => r.status === 200 && !r.url.includes('/sign-in'),
  });
  if (!signedIn) fail('sign-in failed; check EMAIL and PASSWORD');

  for (const page of PAGES) {
    const url = `${BASE_URL}/projects/${PROJECT_ID}${page ? `/${page}` : ''}`;
    const res = http.get(url);
    check(res, {
      [`${page || 'overview'}: 200`]: (r) => r.status === 200,
      [`${page || 'overview'}: no error page`]: (r) => !r.body.includes('couldn’t load'),
      [`${page || 'overview'}: not signed out`]: (r) => !r.url.includes('/sign-in'),
    });
  }
}
